// Which 3D model (public/models/*.glb) each product uses. Generated by scripts/build-3d-models.mjs
// (BU100E by scripts/build-bu100e-model.mjs). Every product has a model; unknown slugs fall back to the photo card.
const M = {
  bu100e: 'bu100e',
  bu100ew: 'bu100e',
  bu30e: 'bu30e',
  bu200e: 'su-short',
  bu200ew: 'su-short',
  'su102-h114': 'su-short',
  bu300e: 'su-tall',
  bu300ew: 'su-tall',
  'su103-h114': 'su-tall',
  'se30-st': 'se',
  'se100-st': 'se',
  'se100w-st': 'se',
  'su102-st': 'su-st',
  'su102w-st': 'su-st',
  al100: 'al100',
  wg100: 'el-wg-100',
  dwg100: 'el-wg-100',
  we100: 'el-we-100',
  ws10: 'ws-cartridge',
  'ws10-25': 'ws-cartridge',
  'ws20-01': 'ws-cartridge',
  'ws20-25': 'ws-cartridge',
  'serie-l': 'strainer-l',
  'serie-ll': 'strainer-ll',
  'serie-of-75s': 'strainer-of',
  mga: 'mag-plate-short',
  mgb110: 'mag-plate-long',
  mgb160: 'mag-disc',
  mgb210: 'mag-box',
  mgr200: 'mag-rect',
  ss102: 'ss',
  ss103: 'ss',
  ss305: 'ss',
  ss306: 'ss',
  ss12pf20: 'ss',
  'osca-cs-ss-ss-pf-media-capacidade': 'osca-cart',
  'osca-cs-su-su-pf': 'osca-su',
  'osca-cs-al-al-pf': 'osca-al',
  'osca-cs-ss-ss-pf-alta-capacidade': 'osca-ss-alta',
  'osca-os': 'osca-os',
  'trcs-100': 'trcs',
  'bf-20': 'bf-20',
  'trvs-10e': 'trvs',
  'trvs-30e': 'trvs',
  'trvs-70e': 'trvs',
  'trvs-n30e': 'trvs-n',
  'ws-wd': 'ws-wd',
  'ws-wd-1pf': 'ws-wd',
  'ws-su103-1r-ws20': 'ws-wd',
  'trap-40': 'trap',
  'trap-60': 'trap',
  'trap-100': 'trap',
  'trap-150': 'trap',
  'trap-200': 'trap',
  'desareador-quicktron-50': 'quicktron',
  'desareador-quicktron-100': 'quicktron',
  'desareador-quicktron-50-sus': 'quicktron',
  'desareador-quicktron-100-sus': 'quicktron',
  'caminhao-de-filtragem': 'truck'
};
// filter elements M/E/X/D: <kind><size>-H<height> → el-<kind>-<size>-<height>
const element = slug => {
  const m = /^([mexd])(\d+)-h(\d+)$/.exec(slug);
  return m ? `el-${m[1]}-${m[2]}-${m[3]}` : null;
};

export const model3d = slug => {
  const key = M[slug] || element(slug);
  return key ? `/models/${key}.glb` : null;
};
